299	        String last3 = letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
300	        String normalizedCity = normalizeForComparison(city);
301	        int sequence = (int) this.clinicService.findAllOwners().stream()
302	            .filter(existing -> normalizedCity.equals(normalizeForComparison(existing.getCity())))
303	            .count() + 1;
304	        return String.format("%s-%s-%04d", city3, last3, sequence);
