343	    /**
344	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets are stripped.
345	     * A leading {@code '+'} and its country code are kept as-is; otherwise the country code {@code '+61'}
346	     * is assumed and a single leading {@code '0'} is dropped from the national digits. The result must be
347	     * a {@code '+'} followed by 8 to 15 digits. For example {@code "0412 345 678"} normalizes to
348	     * {@code "+61412345678"}. The E.164 string is what gets stored and returned.
349	     *
350	     * @param telephone the raw telephone value from the submitted owner payload
351	     * @return the normalized E.164 telephone number
352	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
353	     */
354	    private String normalizeTelephone(String telephone) {
355	        String raw = telephone == null ? "" : telephone.strip();
356	        boolean hasCountryCode = raw.startsWith("+");
357	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
358	        String digits;
359	        if (hasCountryCode) {
360	            digits = cleaned.substring(1);
361	        } else {
362	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
363	            digits = "61" + national;
364	        }
365	        if (!digits.matches("[0-9]{8,15}")) {
366	            throw new InvalidOwnerFieldsException(List.of("telephone"));
367	        }
368	        return "+" + digits;
369	    }
