406	    /**
407	     * Rejects creating an owner whose E.164 telephone is already used by any other owner.
408	     * Existing owners' telephones are converted to E.164 form before comparison so that
409	     * differently-formatted representations of the same number are treated as duplicates.
410	     *
411	     * @param normalizedTelephone the E.164 telephone of the owner being created
412	     * @throws DuplicateOwnerTelephoneException if another owner already uses the same E.164 telephone
413	     */
414	    private void rejectDuplicateTelephone(String normalizedTelephone) {
415	        boolean duplicate = this.clinicService.findAllOwners().stream()
416	            .map(Owner::getTelephone)
417	            .filter(telephone -> telephone != null)
418	            .map(this::toE164OrNull)
419	            .filter(telephone -> telephone != null)
420	            .anyMatch(normalizedTelephone::equals);
421	        if (duplicate) {
422	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
423	        }
424	    }
425	
426	    /**
427	     * The maximum number of owners a single city may contain. Once a city already holds this many
428	     * owners, creating another owner in that city is rejected.
429	     */
430	    private static final int MAX_OWNERS_PER_CITY = 50;
431	
432	    /**
433	     * Rejects creating an owner in a city that already contains {@link #MAX_OWNERS_PER_CITY} or more
434	     * owners. Existing owners' cities are compared case-insensitively with surrounding and repeated
435	     * internal whitespace collapsed (see {@link #normalizeForComparison}), matching the per-city
436	     * counting used elsewhere.
437	     *
438	     * @param city the city of the owner being created
439	     * @throws OwnerCityCapacityExceededException if the city already contains the maximum number of owners
440	     */
441	    /**
442	     * The maximum number of owners that may be registered on a single day. Once this many owners
443	     * already share a {@code registrationDate}, creating another owner for that day is rejected.
444	     */
445	    private static final int MAX_OWNERS_PER_DAY = 100;
446	
447	    /**
448	     * Rejects creating an owner on a day that has already reached {@link #MAX_OWNERS_PER_DAY} or more
449	     * owner registrations. Existing owners are counted by their {@code registrationDate} matching the
450	     * registration date of the owner being created.
451	     *
452	     * @param registrationDate the registration date of the owner being created
453	     * @throws DailyOwnerLimitExceededException if the day has already reached the maximum number of owners
454	     */
455	    /**
456	     * Rolls an effective registration date forward onto a business day. A registration date must fall
457	     * on a weekday: when the supplied or defaulted date is a Saturday or Sunday it is rolled forward to
458	     * the next Monday and that adjusted date becomes the owner's {@code registrationDate}. A weekday date
459	     * is returned unchanged. Every value derived from the registration date (the daily create-limit
460	     * count, the membership number's year segment, and so on) uses this adjusted date.
461	     *
462	     * @param date the effective registration date (supplied in the request or defaulted to the server date)
463	     * @return the same date if it is a weekday, otherwise the following Monday
464	     */
465	    private LocalDate rollToBusinessDay(LocalDate date) {
466	        DayOfWeek day = date.getDayOfWeek();
467	        if (day == DayOfWeek.SATURDAY) {
468	            return date.plusDays(2);
469	        }
470	        if (day == DayOfWeek.SUNDAY) {
471	            return date.plusDays(1);
472	        }
473	        return date;
474	    }
475	
476	    private void rejectDailyLimitReached(LocalDate registrationDate) {
477	        long ownersToday = this.clinicService.findAllOwners().stream()
478	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
479	            .count();
480	        if (ownersToday >= MAX_OWNERS_PER_DAY) {
481	            throw new DailyOwnerLimitExceededException(registrationDate);
482	        }
483	    }
484	
485	    /**
486	     * The number of owners that must already share a {@code registrationDate} before a newly created
487	     * owner for that day is flagged with a bulk-signup warning. Once more than this many owners have
488	     * been created for the day, the new owner's {@code bulkSignupWarning} is {@code true}.
489	     */
490	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
491	
492	    /**
493	     * Determines whether the owner being created should carry a bulk-signup warning. The warning is
494	     * raised when more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created for
495	     * the same registration date at the time this owner is created. Existing owners are counted by their
496	     * {@code registrationDate} matching the registration date of the owner being created, mirroring the
497	     * daily create-limit accumulation.
498	     *
499	     * @param registrationDate the registration date of the owner being created
500	     * @return {@code true} if the day already holds more than the threshold number of owners
501	     */
502	    private boolean isBulkSignupDay(LocalDate registrationDate) {
503	        long ownersToday = this.clinicService.findAllOwners().stream()
504	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
505	            .count();
506	        return ownersToday > BULK_SIGNUP_WARNING_THRESHOLD;
507	    }
508	
509	    private void rejectCityAtCapacity(String city) {
510	        String normalizedCity = normalizeForComparison(city);
511	        long ownersInCity = this.clinicService.findAllOwners().stream()
512	            .filter(existing -> normalizedCity.equals(normalizeForComparison(existing.getCity())))
513	            .count();
514	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
515	            throw new OwnerCityCapacityExceededException(city);
516	        }
517	    }
518	
519	    /**
520	     * Rejects creating an owner whose last name and address both match an existing owner. Both fields
521	     * are compared case-insensitively with surrounding and repeated internal whitespace collapsed, so
522	     * that e.g. {@code "  110  W. Liberty  St. "} and {@code "110 w. liberty st."} are treated as the
523	     * same address. This guard is bypassed for a request that sets {@code sharesHousehold} true.
524	     *
525	     * @param lastName the last name of the owner being created
526	     * @param address the address of the owner being created
527	     * @throws DuplicateOwnerHouseholdException if another owner shares the same last name and address
528	     */
529	    private void rejectDuplicateHousehold(String lastName, String address) {
530	        String normalizedLastName = normalizeForComparison(lastName);
531	        String normalizedAddress = normalizeAddress(address);
532	        boolean duplicate = this.clinicService.findAllOwners().stream()
533	            .anyMatch(existing -> normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
534	                && normalizedAddress.equals(normalizeAddress(existing.getAddress())));
535	        if (duplicate) {
536	            throw new DuplicateOwnerHouseholdException(lastName, address);
537	        }
538	    }
539	
540	    /**
541	     * Assigns the owner being created a household identifier when the request opts into sharing a
542	     * household. The identifier is a stable value derived from the owner's normalized last name and
543	     * address (see {@link #householdId}), so every owner in the same household is given the exact same
544	     * value regardless of creation order. Any already-existing owner in the same household that has no
545	     * identifier yet is back-filled with the same value so the whole household stays consistent.
546	     *
547	     * @param owner the owner being created, whose household id is set in place
548	     */
549	    private void assignHousehold(Owner owner) {
550	        String householdId = householdId(owner.getLastName(), owner.getAddress());
551	        String normalizedLastName = normalizeForComparison(owner.getLastName());
552	        String normalizedAddress = normalizeAddress(owner.getAddress());
553	        for (Owner existing : this.clinicService.findAllOwners()) {
554	            if (existing.getHouseholdId() == null
555	                && normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
556	                && normalizedAddress.equals(normalizeAddress(existing.getAddress()))) {
557	                existing.setHouseholdId(householdId);
558	                this.clinicService.saveOwner(existing);
559	            }
560	        }
561	        owner.setHouseholdId(householdId);
562	    }
563	
564	    /**
565	     * Counts how many owners belong to the household the owner being created has just been assigned to,
566	     * inclusive of that owner. Existing owners are matched by their {@code householdId} equalling the
567	     * given identifier; the owner being created is added on because it is counted before being persisted.
568	     * An owner that did not opt into a shared household (its {@code householdId} is {@code null}) is a
569	     * household of one. The value is snapshotted on the owner.
570	     *
571	     * @param householdId the household identifier assigned to the owner being created, may be {@code null}
572	     * @return the number of household members, including the owner being created
573	     */
574	    private int countHousehold(String householdId) {
575	        if (householdId == null) {
576	            return 1;
577	        }
578	        long existing = this.clinicService.findAllOwners().stream()
579	            .filter(owner -> householdId.equals(owner.getHouseholdId()))
580	            .count();
581	        return (int) existing + 1;
582	    }
583	
584	    /**
585	     * Derives the stable household identifier for a given last name and address. The value is
586	     * {@code 'HH-' + <12 upper-case hex chars>} of the SHA-256 digest of the normalized last name and
587	     * address (see {@link #normalizeForComparison}), joined by a delimiter. Two owners that resolve to
588	     * the same household therefore always produce the same identifier.
589	     *
590	     * @param lastName the owner's last name
591	     * @param address the owner's address
592	     * @return the stable household identifier
593	     */
594	    private String householdId(String lastName, String address) {
595	        String key = normalizeForComparison(lastName) + "\n" + normalizeAddress(address);
596	        try {
597	            byte[] digest = MessageDigest.getInstance("SHA-256")
598	                .digest(key.getBytes(StandardCharsets.UTF_8));
599	            StringBuilder hex = new StringBuilder();
600	            for (int i = 0; i < 6; i++) {
601	                hex.append(String.format("%02X", digest[i]));
602	            }
603	            return "HH-" + hex;
604	        } catch (NoSuchAlgorithmException ex) {
605	            throw new IllegalStateException("SHA-256 not available", ex);
606	        }
607	    }
608	
609	    /**
610	     * Normalizes a value for case-insensitive, whitespace-insensitive comparison: leading and trailing
611	     * whitespace is stripped, every run of internal whitespace is collapsed to a single space, and the
612	     * result is lower-cased. A {@code null} value normalizes to the empty string.
613	     *
614	     * @param value the value to normalize, may be {@code null}
615	     * @return the normalized value
616	     */
617	    private String normalizeForComparison(String value) {
618	        if (value == null) {
619	            return "";
620	        }
621	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
622	    }
623	
624	    /**
625	     * Normalizes an owner address for storage and comparison: leading and trailing whitespace is
626	     * stripped, every run of internal whitespace is collapsed to a single space, the value is
627	     * upper-cased, and common street-type abbreviations are expanded ({@code ST -> STREET},
628	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). For example {@code "  12  main  st "} normalizes to
629	     * {@code "12 MAIN STREET"}. A {@code null} value normalizes to the empty string. This is the form
630	     * that is stored, returned, and used for every address comparison (household duplicate detection
631	     * and the shared household id).
632	     *
633	     * @param address the raw address value from the submitted owner payload, may be {@code null}
634	     * @return the normalized address
635	     */
636	    private String normalizeAddress(String address) {
637	        if (address == null) {
638	            return "";
639	        }
640	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
641	        if (collapsed.isEmpty()) {
642	            return "";
643	        }
644	        String[] tokens = collapsed.split(" ");
645	        StringBuilder normalized = new StringBuilder();
646	        for (int i = 0; i < tokens.length; i++) {
647	            if (i > 0) {
648	                normalized.append(' ');
649	            }
650	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
651	        }
652	        return normalized.toString();
653	    }
654	}
